(3168652, 445335, 41047, '<td valign="top">i love the title :)</td>', 'i love the title :)', '2007-01-01 23:42:55.000000', NULL, 1),
(3168653, 445002, 12200, '<td valign="top">Seems like it should be on the cover of a greeting card, don''t you think?</td>', 'Seems like it should be on the cover of a greeting card, don''t you think?', '2007-01-01 23:43:58.000000', NULL, 1),
(3168658, 444775, 12200, '<td valign="top">This is a great, striking photo as it is. I would love to see the effect in black and white, though...because I think the clarity on his beard is incredible and is just inviting the duotone effect.</td>', 'This is a great, striking photo as it is. I would love to see the effect in black and white, though...because I think the clarity on his beard is incredible and is just inviting the duotone effect.', '2007-01-01 23:46:10.000000', NULL, 1),
