(3169124, 441439, 59415, '<td valign="top">Very nice.  I like the composition.</td>', 'Very nice.  I like the composition.', '2007-01-02 02:59:54.000000', NULL, 1),
(3169126, 442365, 59415, '<td valign="top">This has a very carefree feel.  I really enjoy the surf pounding and being stopped in motion while the bird seems un fazed and poised to maybe make a meal out of some stray fish.</td>', 'This has a very carefree feel.  I really enjoy the surf pounding and being stopped in motion while the bird seems un fazed and poised to maybe make a meal out of some stray fish.', '2007-01-02 03:01:07.000000', NULL, 1),
(3169127, 443757, 59415, '<td valign="top">Very cool lightng.  I like the way you did this.  I might crop a bit out of the top...?  But that is just me.  8</td>', 'Very cool lightng.  I like the way you did this.  I might crop a bit out of the top...?  But that is just me.  8', '2007-01-02 03:01:56.000000', NULL, 1),
