(3172083, 444907, 12200, '<td valign="top">Ill-focused.</td>', 'Ill-focused.', '2007-01-02 18:58:01.000000', NULL, 1),
(3172087, 442442, 12200, '<td valign="top">I would burn that sunspot on the right side. It''s pretty distracting.</td>', 'I would burn that sunspot on the right side. It''s pretty distracting.', '2007-01-02 18:58:53.000000', NULL, 1),
(3172098, 442225, 6999, '<td valign="top">Very bright this - the sky has gone to something far too pale to be interesting. The composition is OK, but perhaps could be more successful with a variety of zones to attract the eye - this is very much in a single line across frame, and perhaps some foreground, or progression of distance into the shot, would help.</td>', 'Very bright this - the sky has gone to something far too pale to be interesting. The composition is OK, but perhaps could be more successful with a variety of zones to attract the eye - this is very much in a single line across frame, and perhaps some foreground, or progression of distance into the shot, would help.', '2007-01-02 19:03:10.000000', NULL, 1),
(3172099, 444274, 64637, '<td valign="top">What a great photo. Congratulations.</td>', 'What a great photo. Congratulations.', '2007-01-02 19:03:42.000000', NULL, 1),
(3172106, 445002, 59415, '<td valign="top">Now you done made me want to go and get another puppy.  Dang that is cute.</td>', 'Now you done made me want to go and get another puppy.  Dang that is cute.', '2007-01-02 19:05:22.000000', NULL, 1),
(3172107, 440034, 12200, '<td valign="top">Looks like you tried the unsharp mask... I''m not positive, of course....but the whole foreground remains blurry to me. The background, meanwhile, is gorgeous.</td>', 'Looks like you tried the unsharp mask... I''m not positive, of course....but the whole foreground remains blurry to me. The background, meanwhile, is gorgeous.', '2007-01-02 19:05:24.000000', NULL, 1),
(3172110, 445290, 12200, '<td valign="top">Reminds me of a holiday church bulletin. Very nicely done.</td>', 'Reminds me of a holiday church bulletin. Very nicely done.', '2007-01-02 19:06:15.000000', NULL, 1),
(3172115, 445233, 69493, '<td valign="top">Great colors, I would have cropped closer to see more details in the face.  But thats just me.  Great capture!!!</td>', 'Great colors, I would have cropped closer to see more details in the face.  But thats just me.  Great capture!!!', '2007-01-02 19:06:57.000000', NULL, 1),
(3172116, 440082, 67301, '<td valign="top">this shot has good focus but has no sparkle and seems drab and washed out. sorry</td>', 'this shot has good focus but has no sparkle and seems drab and washed out. sorry', '2007-01-02 19:06:59.000000', NULL, 1),
